export function connectPresence(socket, onPresence) {
  socket.connect();
  socket.on('presence', onPresence);
  return () => socket.off('presence', onPresence);
}

productBefore.test/connect.test.js:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { EventEmitter } from 'node:events';
import { connectPresence } from '../src/connect.js';
test('presence after connect', () => {
  const socket = new EventEmitter();
  socket.connect = () => {};
  const seen = [];
  const dispose = connectPresence(socket, value => seen.push(value));
  socket.emit('presence', 'online');
  assert.deepEqual(seen, ['online']);
  dispose();
  assert.equal(socket.listenerCount('presence'), 0);
});

